Proxy: {
  onBeforeAddons(manager, param) {
    if (param.Locked) {
      manager.disallowFeature("changeProxySettings");
      lazy.ProxyPolicies.configureProxySettings(
        param,
        lazy.PoliciesUtils.setAndLockPref
      );
    } else {
      lazy.ProxyPolicies.configureProxySettings(
        param,
        lazy.PoliciesUtils.setDefaultPref
      );
    }
  },
},
